// ===== Validações estruturais e fiscais da NF-e (papel do GRC NF-e / J1B*) =====
const body = $json.body ?? $json;
const raiz = body.xml ?? body;
const nfe = raiz.nfeProc?.NFe?.infNFe ?? raiz.NFe?.infNFe;
if (!nfe) throw new Error('XML não é uma NF-e válida (infNFe não encontrado)');
const det = Array.isArray(nfe.det) ? nfe.det[0] : nfe.det;
const prod = det.prod;
const chave = String(nfe.$?.Id ?? nfe.Id ?? '').replace('NFe', '');

// --- Dígito verificador da chave de acesso (módulo 11, pesos 2..9) ---
const pesos = [2, 3, 4, 5, 6, 7, 8, 9];
let soma = 0;
[...chave.slice(0, 43)].reverse().forEach((d, i) => { soma += Number(d) * pesos[i % 8]; });
const resto = soma % 11;
const dv = (resto === 0 || resto === 1) ? '0' : String(11 - resto);

const erros = [];
if (chave.length !== 44) {
  erros.push(`Chave de acesso com ${chave.length} dígitos (esperado 44)`);
} else if (dv !== chave[43]) {
  erros.push(`DV da chave de acesso inválido (calculado ${dv}, informado ${chave[43]})`);
}

// --- Mapeamento CFOP de saída do fornecedor -> CFOP de entrada nossa ---
// 5xxx (dentro do estado) -> 1xxx | 6xxx (fora do estado) -> 2xxx | 7xxx (exterior) -> 3xxx
const cfopSaida = String(prod.CFOP);
const mapa = { '5': '1', '6': '2', '7': '3' };
const cfopEntrada = (mapa[cfopSaida[0]] ?? '?') + cfopSaida.slice(1);
if (!mapa[cfopSaida[0]]) {
  erros.push(`CFOP ${cfopSaida} não é CFOP de saída do fornecedor (esperado 5xxx/6xxx/7xxx)`);
}

const icms = det.imposto?.ICMS?.ICMS00 ?? {};
const ipi = det.imposto?.IPI?.IPITrib ?? {};

return [{ json: {
  chave,
  errosEstruturais: erros,
  cnpjEmitente: String(nfe.emit.CNPJ),
  nomeEmitente: nfe.emit.xNome,
  numeroNF: String(nfe.ide.nNF),
  pedido: String(prod.xPed ?? ''),
  itemPedido: String(prod.nItemPed ?? '').padStart(5, '0').replace(/^000(\d0)$/, '000$1'),
  material: prod.cProd,
  ncm: String(prod.NCM),
  cfopSaida,
  cfopEntrada,
  quantidade: Number(prod.qCom),
  valorUnitario: Number(prod.vUnCom),
  valorProdutos: Number(prod.vProd),
  vBC: Number(icms.vBC ?? 0),
  pICMS: Number(icms.pICMS ?? 0),
  vICMS: Number(icms.vICMS ?? 0),
  pIPI: Number(ipi.pIPI ?? 0),
  vIPI: Number(ipi.vIPI ?? 0),
  valorTotalNF: Number(nfe.total.ICMSTot.vNF)
} }];

// ===== Three-way match (Pedido x NF-e x qtde aberta) + validação tributária =====
const nf = $('Validações Fiscais NF-e').item.json;
const po = $json;
const div = [...(nf.errosEstruturais || [])];

const itens = po.Items || [];
const item = itens.find(i => Number(i.PurchaseOrderItem) === Number(nf.itemPedido)) ?? itens[0];
if (!item) div.push(`Item ${nf.itemPedido} não encontrado no pedido ${nf.pedido}`);

// Fornecedor: CNPJ do emitente da NF-e deve ser o CNPJ do fornecedor do pedido
if (po.Supplier?.TaxNumber1 && po.Supplier.TaxNumber1 !== nf.cnpjEmitente) {
  div.push(`CNPJ emitente ${nf.cnpjEmitente} diverge do fornecedor do pedido (${po.Supplier.TaxNumber1})`);
}

if (item) {
  // Preço (tolerância 1% - espelha OMR6)
  if (Math.abs(Number(item.NetPriceAmount) - nf.valorUnitario) > Number(item.NetPriceAmount) * 0.01) {
    div.push(`Preço unitário da NF (${nf.valorUnitario}) diverge do pedido (${item.NetPriceAmount})`);
  }
  // Quantidade aberta
  const aberta = Number(item.OrderQuantity) - Number(item.QuantityDelivered);
  if (nf.quantidade > aberta) {
    div.push(`Quantidade da NF (${nf.quantidade}) excede a qtde aberta do pedido (${aberta})`);
  }
  // CFOP de entrada esperado (determinação de CFOP da localização BR)
  if (item.CFOPExpected && nf.cfopEntrada !== item.CFOPExpected) {
    div.push(`CFOP de entrada ${nf.cfopEntrada} (derivado de ${nf.cfopSaida}) diverge do esperado ${item.CFOPExpected}`);
  }
  // NCM
  if (item.NCM && String(item.NCM) !== nf.ncm) {
    div.push(`NCM da NF (${nf.ncm}) diverge do cadastro do material (${item.NCM})`);
  }
}

// Consistência do imposto destacado: vICMS = vBC x alíquota
const icmsCalc = nf.vBC * nf.pICMS / 100;
if (Math.abs(icmsCalc - nf.vICMS) > 0.02) {
  div.push(`vICMS destacado (${nf.vICMS}) inconsistente com base x alíquota (${icmsCalc.toFixed(2)})`);
}
// Regra fiscal da operação: interna MG, contribuinte, esperado 18%
if (nf.pICMS !== 18) {
  div.push(`Alíquota de ICMS ${nf.pICMS}% diverge dos 18% esperados para operação interna MG (J1BTAX)`);
}

return [{ json: {
  aprovado: div.length === 0,
  divergencias: div,
  nf,
  migo: {
    PurchaseOrder: nf.pedido,
    PurchaseOrderItem: item ? item.PurchaseOrderItem : nf.itemPedido,
    QuantityInEntryUnit: nf.quantidade,
    NFeAccessKey: nf.chave
  },
  miro: {
    PurchaseOrder: nf.pedido,
    Supplier: po.Supplier?.Supplier,
    InvoiceGrossAmount: nf.valorTotalNF,
    NFeAccessKey: nf.chave,
    NFeNumber: nf.numeroNF,
    CFOP: nf.cfopSaida,
    TaxAmountICMS: nf.vICMS,
    TaxAmountIPI: nf.vIPI
  }
} }];
